nf=json.load(open('novel-forms.json')); kn=json.load(open('known-forms.json'))
out=dict(sorted(G.items()))
out["__broaden__"]={}
for k,v in B.items():
    assert k in kn,k
    out["__broaden__"][k]=kn[k]+" · also "+v
json.dump(out,open('gloss.json','w'),ensure_ascii=False,indent=1)
miss=set(nf)-set(G);extra=set(G)-set(nf)
print(len(G),len(B),'missing',miss,'extra',extra)
for k,v in list(G.items())+list(out["__broaden__"].items()):
    if len(v)>=230 or ' — ' not in v: print('BAD',k,len(v))
